def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# Leer número del usuario
numero = int(input("Introduce un índice: "))

# Obtener el valor en ese índice de la secuencia de Fibonacci
resultado = fibonacci(numero)

print(f"El valor en el índice {numero} de la secuencia de Fibonacci es: {resultado}")

