def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# Gerar matriz com todos os números primos entre 1 e 1000
primes = [n for n in range(1, 1001) if is_prime(n)]

# Receber entrada do usuário
n = int(input("Digite um índice (0 a {}): ".format(len(primes) - 1)))

# Retornar o valor no índice especificado
if 0 <= n < len(primes):
    print("O número primo no índice {} é: {}".format(n, primes[n]))
else:
    print("Índice fora do intervalo válido.")

