    try:
        index = int(input("Dizideki hangi indeksteki değeri görmek istiyorsunuz? (0-9 arasında): "))
        if 0 <= index < n:
            break
        else:
            print("Lütfen 0 ile 9 arasında bir indeks girin.")
    except ValueError:
        print("Geçersiz giriş! Lütfen bir tam sayı girin.")

# İlgili indeksteki değeri döndür
print(f"Dizinin {index}. indeksindeki değeri: {dizi[index]}")
